use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts granted by `HTTPClient<[...]>` on this node. A request outside the set
/// traps at the boundary, so it is recorded as a failure here instead of being
/// sent. One bad subscription then cannot take down the whole tick.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key under which each call's input is recorded in the shared store.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

/// Extract the host of an `http`/`https` URL, lowercased, without userinfo or port.
fn host_of(url: &str) -> Option<String> {
    let rest = if let Some(r) = strip_prefix_ci(url, "https://") {
        r
    } else if let Some(r) = strip_prefix_ci(url, "http://") {
        r
    } else {
        return None;
    };
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    if s.len() >= prefix.len()
        && s.is_char_boundary(prefix.len())
        && s[..prefix.len()].eq_ignore_ascii_case(prefix)
    {
        Some(&s[prefix.len()..])
    } else {
        None
    }
}

fn host_allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|h| *h == host)
}

/// Encode a string as a JSON string literal.
fn json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                let code = c as u32;
                out.push_str("\\u00");
                let hex = b"0123456789abcdef";
                out.push(hex[(code >> 4) as usize] as char);
                out.push(hex[(code & 0xf) as usize] as char);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialise the input `subscription-list` as JSON: `{"urls":[...]}`.
fn encode_input(subs: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subs.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_string(&mut out, url);
    }
    out.push_str("]}");
    out
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received (approved state-rw grant).
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let host = match host_of(&url) {
                Some(h) => h,
                None => {
                    failures.push(FetchFailure {
                        url,
                        error: "unsupported or malformed URL".to_string(),
                    });
                    continue;
                }
            };
            if !host_allowed(&host) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
